def publish_rounds_as_before(apps, schema_editor):
    """Rounds used to be in rankings since their results date, or since their
    start with results visible during rounds; now the public results date
    decides, so it is set to that moment to keep rankings as they were.
    """
    CzecieCampConfig = apps.get_model("czeciecamp", "CzecieCampConfig")
    Round = apps.get_model("contests", "Round")
    for config in CzecieCampConfig.objects.all():
        for round in Round.objects.filter(contest_id=config.contest_id):
            if config.results_visible_during_round:
                round.public_results_date = round.start_date
                # Personal results cannot come later than the public ones.
                if round.results_date is None or round.results_date > round.public_results_date:
                    round.results_date = round.public_results_date
            else:
                round.public_results_date = round.results_date
            round.save(update_fields=["results_date", "public_results_date"])


